# Maybe 2 on left = 9 on right, and 7 on left = 7 on right?

def check_correspondence(left, right):
    """Check if left cell L corresponds to right cell R at same position"""
    mismatches = []
    matches = []
    for i in range(len(left)):
        for j in range(len(right)):
            pair = (left[i][j], right[i][j])
            if pair == (2, 9):
                matches.append("2->9")
            elif pair == (7, 7):
                matches.append("7->7")
            elif pair == (2, 7) or pair == (9, 2):
                mismatches.append(f"{pair[0]}->{pair[1]}")
            elif pair == (9, 9) or pair == (2, 2):
                mismatches.append(f"{pair[0]}->{pair[1]}")
    return matches[:20], mismatches[:20]

